arguments.file_text:
@page "/settings"
@rendermode InteractiveServer
@using sv_f0225c308ee047e7bf32e458813bc3e7.Components.Pages.Settings

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetActiveSection" />

    <main class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </main>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

.settings-dashboard {
    display: flex;
    gap: 2rem;
    max-width: 1100px;
    margin: 0 auto;
    padding: 2rem 1rem;
    min-height: 80vh;
}

/* Sidebar */
.settings-sidebar ul {
    list-style: none;
    padding: 0;
    margin: 0;
    min-width: 200px;
}

.settings-sidebar li {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 0.75rem 1rem;
    border-radius: 6px;
    cursor: pointer;
    transition: background-color 0.15s, color 0.15s;
    color: var(--text-secondary, #555);
    font-weight: 500;
}

.settings-sidebar li:hover {
    background-color: var(--hover-bg, #f0f0f0);
}

.settings-sidebar li.active {
    background-color: var(--active-bg, #e3f2fd);
    color: var(--active-color, #1565c0);
    font-weight: 600;
}

.sidebar-icon {
    font-size: 1.2rem;
}

/* Main content area */
.settings-content {
    flex: 1;
    min-width: 0;
}

.settings-section h2 {
    margin-top: 0;
    margin-bottom: 1.5rem;
    font-size: 1.5rem;
    font-weight: 600;
}

.settings-section h3 {
    margin-top: 1.5rem;
    margin-bottom: 0.75rem;
    font-size: 1.1rem;
    font-weight: 600;
}

/* Form elements */
.form-group {
    margin-bottom: 1rem;
}

.form-group label,
.form-group legend {
    display: block;
    font-weight: 500;
    margin-bottom: 0.35rem;
    font-size: 0.9rem;
}

.form-group fieldset {
    border: none;
    padding: 0;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="password"],
.form-group textarea,
.form-group select {
    width: 100%;
    max-width: 400px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
    font-family: inherit;
}

.form-group textarea {
    resize: vertical;
}

.form-group select {
    max-width: 250px;
}

/* Buttons */
.form-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.5rem;
}

.btn-primary {
    padding: 0.5rem 1.25rem;
    background-color: #1565c0;
    color: white;
    border: none;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
    font-weight: 500;
}

.btn-primary:hover {
    background-color: #0d47a1;
}

.btn-secondary {
    padding: 0.5rem 1.25rem;
    background-color: transparent;
    color: #555;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
}

.btn-secondary:hover {
    background-color: #f5f5f5;
}

.btn-danger {
    padding: 0.5rem 1rem;
    background-color: #c62828;
    color: white;
    border: none;
    border-radius: 4px;
    font-size: 0.9rem;
    cursor: pointer;
}

.btn-danger:hover {
    background-color: #b71c1c;
}

.btn-sm {
    padding: 0.3rem 0.75rem;
    font-size: 0.8rem;
}

/* Toggle rows */
.toggle-group {
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}

.toggle-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    max-width: 400px;
    padding: 0.5rem 0;
    cursor: pointer;
}

/* Avatar */
.avatar-preview {
    display: flex;
    align-items: center;
    gap: 1rem;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background-color: #f9f9f9;
    border-radius: 8px;
}

.avatar-image {
    width: 64px;
    height: 64px;
    border-radius: 50%;
    object-fit: cover;
    border: 2px solid #ddd;
}

.avatar-url {
    font-size: 0.8rem;
    color: #777;
    word-break: break-all;
}

/* Toast messages */
.toast {
    margin-top: 1rem;
    padding: 0.75rem 1rem;
    border-radius: 4px;
    font-size: 0.9rem;
    max-width: 400px;
}

.toast-success {
    background-color: #e8f5e9;
    color: #2e7d32;
    border: 1px solid #a5d6a7;
}

.toast-error {
    background-color: #ffebee;
    color: #c62828;
    border: 1px solid #ef9a9a;
}

/* Channel list */
.channel-list {
    list-style: none;
    padding: 0;
    margin: 0;
}

.channel-list li {
    padding: 0.35rem 0;
}

.channel-list label {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    cursor: pointer;
}

/* Expandable panel */
.expandable-panel {
    border: 1px solid #ddd;
    border-radius: 6px;
    margin-bottom: 1.5rem;
}

.panel-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    width: 100%;
    padding: 0.75rem 1rem;
    background: #fafafa;
    border: none;
    border-radius: 6px;
    cursor: pointer;
    font-size: 1rem;
    font-weight: 500;
}

.panel-header:hover {
    background-color: #f0f0f0;
}

.panel-body {
    padding: 1rem;
    border-top: 1px solid #ddd;
}

/* Status indicators */
.status-indicator {
    padding: 0.2rem 0.5rem;
    border-radius: 12px;
    font-size: 0.8rem;
    font-weight: 600;
}

.status-on {
    background-color: #e8f5e9;
    color: #2e7d32;
}

.status-off {
    background-color: #fff3e0;
    color: #e65100;
}

.current-badge {
    font-size: 0.8rem;
    color: #777;
    font-style: italic;
}

.hint-text {
    font-size: 0.85rem;
    color: #777;
    margin-top: 0.5rem;
}

/* Sessions table */
.sessions-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 0.5rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.6rem 0.75rem;
    text-align: left;
    border-bottom: 1px solid #eee;
    font-size: 0.9rem;
}

.sessions-table th {
    font-weight: 600;
    background-color: #fafafa;
}

/* Dialog overlay */
.dialog-overlay {
    position: fixed;
    inset: 0;
    background-color: rgba(0, 0, 0, 0.4);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 1000;
}

.dialog {
    background: white;
    border-radius: 8px;
    padding: 1.5rem;
    max-width: 400px;
    width: 90%;
    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.15);
}

.dialog h4 {
    margin-top: 0;
}

.dialog-actions {
    display: flex;
    gap: 0.75rem;
    margin-top: 1.25rem;
    justify-content: flex-end;
}

/* Radio options */
.radio-option {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    margin-right: 1.25rem;
    cursor: pointer;
    font-weight: normal;
}

/* Appearance preview */
.preview-area {
    margin-top: 1.5rem;
    padding: 1.25rem;
    border: 1px solid #ddd;
    border-radius: 8px;
    transition: all 0.2s;
}

.preview-area h4 {
    margin-top: 0;
}

.preview-card {
    margin-top: 0.75rem;
    padding: 1rem;
    border: 1px solid #ccc;
    border-radius: 6px;
}

/* Theme previews */
.preview-theme-dark {
    background-color: #1e1e1e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-theme-dark .preview-card {
    background-color: #2d2d2d;
    border-color: #555;
}

.preview-theme-light {
    background-color: #ffffff;
    color: #333;
}

.preview-theme-system {
    background-color: #f5f5f5;
    color: #333;
}

/* Font size previews */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.2rem;
}

/* Compact mode preview */
.preview-compact {
    padding: 0.6rem;
    line-height: 1.3;
}

.preview-compact .preview-card {
    padding: 0.5rem;
    margin-top: 0.4rem;
}

/* Loading / empty states */
.loading {
    color: #777;
    font-style: italic;
}

.empty-state {
    color: #999;
    font-style: italic;
}

/* Two-factor section */
.twofa-section {
    margin-bottom: 1.5rem;
}

