+    padding: 1.5rem;
+    max-width: 400px;
+    width: 90%;
+    box-shadow: 0 4px 24px rgba(0, 0, 0, 0.15);
+}
+
+.dialog h4 {
+    margin-top: 0;
+}
+
+.dialog-actions {
+    display: flex;
+    gap: 0.75rem;
+    margin-top: 1.25rem;
+    justify-content: flex-end;
+}
+
+/* Radio options */
+.radio-option {
+    display: inline-flex;
+    align-items: center;
+    gap: 0.35rem;
+    margin-right: 1.25rem;
+    cursor: pointer;
+    font-weight: normal;
+}
+
+/* Appearance preview */
+.preview-area {
+    margin-top: 1.5rem;
+    padding: 1.25rem;
+    border: 1px solid #ddd;
+    border-radius: 8px;
+    transition: all 0.2s;
+}
+
+.preview-area h4 {
+    margin-top: 0;
+}
+
+.preview-card {
+    margin-top: 0.75rem;
+    padding: 1rem;
+    border: 1px solid #ccc;
+    border-radius: 6px;
+}
+
+/* Theme previews */
+.preview-theme-dark {
+    background-color: #1e1e1e;
+    color: #e0e0e0;
+    border-color: #444;
+}
+
+.preview-theme-dark .preview-card {
+    background-color: #2d2d2d;
+    border-color: #555;
+}
+
+.preview-theme-light {
+    background-color: #ffffff;
+    color: #333;
+}
+
+.preview-theme-system {
+    background-color: #f5f5f5;
+    color: #333;
+}
+
+/* Font size previews */
+.preview-font-small {
+    font-size: 0.8rem;
+}
+
+.preview-font-medium {
+    font-size: 1rem;
+}
+
+.preview-font-large {
+    font-size: 1.2rem;
+}
+
+/* Compact mode preview */
+.preview-compact {
+    padding: 0.6rem;
+    line-height: 1.3;
+}
+
+.preview-compact .preview-card {
+    padding: 0.5rem;
+    margin-top: 0.4rem;
+}
+
+/* Loading / empty states */
+.loading {
+    color: #777;
+    font-style: italic;
+}
+
+.empty-state {
+    color: #999;
+    font-style: italic;
+}
+
+/* Two-factor section */
+.twofa-section {
+    margin-bottom: 1.5rem;
+}
+

